        Pose rightPark = p.of(14.5, 95.7, 0);

        // Other poses the paths need (control points, unnamed endpoints).
        Pose toRowApproachControl1 = p.of(62, 30, 0);
        Pose toRowApproachControl2 = p.of(66, 80, 0);
        Pose toRowApproachControl3 = p.of(66, 118, 0);
        Pose toRowApproachControl4 = p.of(44, 116, 0);
        Pose leftLaunchOffsetParkControl1 = p.of(26, 92, 0);
        Pose leftLaunchOffsetToWallFlowerStagingControl1 = p.of(24, 104, 0);
        Pose leftLaunchOffsetToWallFlowerStagingControl2 = p.of(24, 70, 0);
        Pose leftLaunchOffsetToWallFlowerStagingSegment1Start = p.of(23.1, 47.2, 296.4);
        Pose laneRightParkControl1 = p.of(24, 60, 0);
        Pose toGardenRowStartControl1 = p.of(32, 20, 0);
        Pose toGardenRowStartControl2 = p.of(36, 8, 0);
        Pose gardenRowStartParkControl1 = p.of(24, 60, 0);
        Pose toRightLaunchCornerSegment1Start = p.of(30.2, 10.7, 180);
        Pose toRightLaunchCornerSegment1End = p.of(30.2, 10.7, 180);
        Pose toRightLaunchCornerSegment2Start = p.of(30.2, 10.7, 180);
        Pose toRightParkControl1 = p.of(26, 55, 0);

        // Paths, written as the stock Visualizer export writes them.
        Path toRowApproach = Paths.curve(rightStart, toRowApproachControl1, toRowApproachControl2, toRowApproachControl3, toRowApproachControl4, rowApproach).constant(rowApproach);
        Path rowApproachPark = Paths.line(rowApproach, rightPark).linear(rowApproach, rightPark);
        Path rowEndToLeftLaunchOffset = Paths.line(rowApproach, leftLaunchOffset).linear(rowApproach, leftLaunchOffset);
        Path leftLaunchOffsetPark = Paths.curve(leftLaunchOffset, leftLaunchOffsetParkControl1, rightPark).linear(leftLaunchOffset, rightPark);
        Path toScoringFlowerStaging = Paths.line(leftLaunchOffset, scoringFlowerStaging).linear(leftLaunchOffset, scoringFlowerStaging);
