        Path toLeftLaunchOffset = Paths.line(scoringFlowerStaging, leftLaunchOffset).linear(scoringFlowerStaging, leftLaunchOffset);
        Path leftLaunchOffsetToWallFlowerStaging = Paths.curve(leftLaunchOffset, leftLaunchOffsetToWallFlowerStagingControl1, leftLaunchOffsetToWallFlowerStagingControl2, wallFlowerStaging).heading(Interpolator.piecewise().until(0.5, Interpolator.linear(leftLaunchOffsetToWallFlowerStagingSegment1Start, wallFlowerStaging)).until(1, Interpolator.linear(wallFlowerStaging, wallFlowerStaging)));
